package ma.lias.controller;
import ma.lias.entity.Affiliation; import ma.lias.repository.AffiliationRepository; import ma.lias.service.AuditService; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/admin/affiliations") @PreAuthorize("hasRole('ADMIN')")
public class AffiliationController { private final AffiliationRepository repo; private final AuditService audit; public AffiliationController(AffiliationRepository repo, AuditService audit){this.repo=repo;this.audit=audit;} @GetMapping public List<Affiliation> all(){return repo.findAll();} @PostMapping public ResponseEntity<Affiliation> create(@RequestBody Affiliation body){Affiliation saved=repo.save(body); audit.log("CREATE","Affiliation",saved.getId(),"Création"); return ResponseEntity.status(HttpStatus.CREATED).body(saved);} @PutMapping("/{id}") public Affiliation update(@PathVariable Long id,@RequestBody Affiliation body){if(!repo.existsById(id)) throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Introuvable"); body.setId(id); audit.log("UPDATE","Affiliation",id,"Modification"); return repo.save(body);} }
